local LoomHeddleMaker = {}
local PRODUCTS = {
    iron_loom_heddle = { name = "Železna listovnica za statve", ironCost = 2, woodCost = 3, leatherCost = 2, time = 5, cost = 160, prestige = 4, happiness = 2, description = "Železna listovnica za dviganje niti na statvah." },
    bronze_loom_heddle = { name = "Bronasta listovnica za statve", bronzeCost = 2, ironCost = 1, woodCost = 3, leatherCost = 2, time = 7, cost = 390, prestige = 6, happiness = 3, description = "Bronasta listovnica za fino tkanje." },
    silver_loom_heddle = { name = "Srebrna listovnica za statve", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 2, time = 11, cost = 940, prestige = 11, happiness = 4, description = "Srebrna listovnica za plemiške tkače." },
    gilded_loom_heddle = { name = "Pozlačena listovnica za statve", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 15, cost = 2030, prestige = 20, happiness = 5, description = "Pozlačena listovnica za dvorne tkače." },
    jewel_set_loom_heddle = { name = "Draguljasta listovnica za statve", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 19, cost = 4380, prestige = 36, happiness = 7, description = "Draguljasta listovnica za kraljevske tkače." },
    royal_sovereign_loom_heddle = { name = "Kraljevski suverena listovnica za statve", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 2, time = 26, cost = 9400, prestige = 68, happiness = 13, description = "Suverena listovnica z biseri za krono." },
}
local BUILDINGS = {
    loomheddle_workshop = { name = "Listovnična delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    loomheddle_house = { name = "Listovnična hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_loomheddle_atelier = { name = "Mojstrski listovnični atelje", cost = { gold = 2975, wood = 430, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_loomheddle_palace = { name = "Suverena listovnična palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
LoomHeddleMaker.ironStock = 12; LoomHeddleMaker.bronzeStock = 10; LoomHeddleMaker.woodStock = 16; LoomHeddleMaker.leatherStock = 12; LoomHeddleMaker.silverStock = 8; LoomHeddleMaker.goldStock = 6; LoomHeddleMaker.jewelStock = 4; LoomHeddleMaker.pearlStock = 4
LoomHeddleMaker.productStock = {}; LoomHeddleMaker.buildings = {}; LoomHeddleMaker.maker = nil; LoomHeddleMaker.activeMaking = {}; LoomHeddleMaker.totalProducts = 0; LoomHeddleMaker.dayTimer = 0
function LoomHeddleMaker.init() LoomHeddleMaker.ironStock=12; LoomHeddleMaker.bronzeStock=10; LoomHeddleMaker.woodStock=16; LoomHeddleMaker.leatherStock=12; LoomHeddleMaker.silverStock=8; LoomHeddleMaker.goldStock=6; LoomHeddleMaker.jewelStock=4; LoomHeddleMaker.pearlStock=4; LoomHeddleMaker.productStock={}; LoomHeddleMaker.buildings={}; LoomHeddleMaker.maker=nil; LoomHeddleMaker.activeMaking={}; LoomHeddleMaker.totalProducts=0; LoomHeddleMaker.dayTimer=0; print("[LoomHeddleMaker] Royal Loom Heddle Maker System initialized (6 products, 4 buildings)") end
function LoomHeddleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LoomHeddleMaker.maker={name=n or ("Listar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Listar najet: %s (spretnost: %d)",LoomHeddleMaker.maker.name,s),"success") end; return true end
function LoomHeddleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LoomHeddleMaker.build(id) local ok,e=LoomHeddleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LoomHeddleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LoomHeddleMaker.getQualityBonus() local b=0; for _,bd in ipairs(LoomHeddleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LoomHeddleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and LoomHeddleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and LoomHeddleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and LoomHeddleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and LoomHeddleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LoomHeddleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LoomHeddleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LoomHeddleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LoomHeddleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LoomHeddleMaker.buildings==0 then return false,"Potrebna listovnična delavnica" end; if not LoomHeddleMaker.maker then return false,"Potreben listar" end; return true end
function LoomHeddleMaker.make(pt,qty) qty=qty or 1; local ok,e=LoomHeddleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then LoomHeddleMaker.ironStock=LoomHeddleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then LoomHeddleMaker.bronzeStock=LoomHeddleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then LoomHeddleMaker.woodStock=LoomHeddleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then LoomHeddleMaker.leatherStock=LoomHeddleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then LoomHeddleMaker.silverStock=LoomHeddleMaker.silverStock-d.silverCost*qty end; if d.goldCost then LoomHeddleMaker.goldStock=LoomHeddleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LoomHeddleMaker.jewelStock=LoomHeddleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LoomHeddleMaker.pearlStock=LoomHeddleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LoomHeddleMaker.maker then t=math.max(1,t-math.floor(LoomHeddleMaker.maker.skill/13)) end; table.insert(LoomHeddleMaker.activeMaking,{id="loomheddle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LoomHeddleMaker.completeMaking(m) local q=1.0+(LoomHeddleMaker.getQualityBonus()/100); if LoomHeddleMaker.maker then q=q+(LoomHeddleMaker.maker.skill/140) end; q=math.min(2.5,q); LoomHeddleMaker.productStock[m.productType]=(LoomHeddleMaker.productStock[m.productType] or 0)+m.quantity; LoomHeddleMaker.totalProducts=LoomHeddleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LoomHeddleMaker.maker then LoomHeddleMaker.maker.itemsMade=LoomHeddleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LoomHeddleMaker.maker.skill=math.min(100,LoomHeddleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Listovnica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"loomheddle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function LoomHeddleMaker.update(dt) if not _G.state then return end; LoomHeddleMaker.dayTimer=LoomHeddleMaker.dayTimer+dt; if LoomHeddleMaker.dayTimer>=30 then LoomHeddleMaker.dayTimer=0; for i=#LoomHeddleMaker.activeMaking,1,-1 do local m=LoomHeddleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LoomHeddleMaker.completeMaking(m); table.remove(LoomHeddleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LoomHeddleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LoomHeddleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LoomHeddleMaker.getStats() return {ironStock=LoomHeddleMaker.ironStock,bronzeStock=LoomHeddleMaker.bronzeStock,woodStock=LoomHeddleMaker.woodStock,leatherStock=LoomHeddleMaker.leatherStock,silverStock=LoomHeddleMaker.silverStock,goldStock=LoomHeddleMaker.goldStock,jewelStock=LoomHeddleMaker.jewelStock,pearlStock=LoomHeddleMaker.pearlStock,productStock=LoomHeddleMaker.productStock,numBuildings=#LoomHeddleMaker.buildings,hasMaker=LoomHeddleMaker.maker~=nil,makerName=LoomHeddleMaker.maker and LoomHeddleMaker.maker.name or "—",makerSkill=LoomHeddleMaker.maker and LoomHeddleMaker.maker.skill or 0,activeMaking=#LoomHeddleMaker.activeMaking,totalProducts=LoomHeddleMaker.totalProducts} end
return LoomHeddleMaker
